import {clone} from './model.mjs';
export const semanticName=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const signature=s=>{let hash=2166136261;for(const c of semanticName(s))hash=Math.imul(hash^c.charCodeAt(0),16777619);return (hash>>>0).toString(16);};
export function entityDescriptor(entity,kind){if(!entity)return null;return {kind,key:entity.semanticId||entity.catalogId||semanticName(entity.title),label:entity.title,contentSignature:signature(entity.body),semanticId:entity.semanticId||null,catalogId:entity.catalogId||null,form:kind==='ritual'?(entity.ritualForm||'Básica'):null,element:kind==='ritual'?(entity.ritualElement||String(entity.meta||'').split('/')[0].trim()):null};}
export function bindingKind(b){return b.type==='ability'||b.binding?.startsWith('ability')?'ability':b.type==='ritualPart'||b.binding?.startsWith('ritual')?'ritual':null;}
export function describeBlock(b,doc){const kind=bindingKind(b);if(!kind)return null;return entityDescriptor((kind==='ability'?doc.abilities:doc.rituals).find(e=>e.id===b.ref),kind);}
export function bindingSlot(b){return b.dataBinding?JSON.stringify(b.dataBinding):b.abilityIndex!==undefined?'legacy-ability-'+b.abilityIndex:b.ritualIndex!==undefined?'legacy-ritual-'+b.ritualIndex:'unbound-'+b.id;}
export function matchBinding(descriptor,doc){if(!descriptor)return {entity:null,reason:'Modelo antigo sem identidade semântica; escolha uma correspondência.'};const list=descriptor.kind==='ability'?doc.abilities:doc.rituals;let candidates=list.filter(e=>{const target=entityDescriptor(e,descriptor.kind);if(descriptor.semanticId){if(target.semanticId)return target.semanticId===descriptor.semanticId;return semanticName(e.title)===semanticName(descriptor.label)&&target.contentSignature===descriptor.contentSignature;}if(descriptor.catalogId)return (target.catalogId===descriptor.catalogId||!target.catalogId&&semanticName(e.title)===semanticName(descriptor.label))&&semanticName(target.form)===semanticName(descriptor.form)&&semanticName(target.element)===semanticName(descriptor.element);return semanticName(e.title)===semanticName(descriptor.label)&&(descriptor.kind!=='ability'||!descriptor.contentSignature||target.contentSignature===descriptor.contentSignature)&&(!descriptor.form||semanticName(target.form)===semanticName(descriptor.form))&&(!descriptor.element||semanticName(target.element)===semanticName(descriptor.element));});return candidates.length===1?{entity:candidates[0],reason:null}:{entity:null,reason:candidates.length?'Há mais de uma correspondência; escolha o vínculo.':'Não há equivalência no repertório de destino.'};}
export function bindingRequirements(item,doc){const seen=new Set(),result=[];for(const b of item.blocks||[]){const kind=bindingKind(b);if(!kind)continue;const key=bindingSlot(b);if(seen.has(key))continue;seen.add(key);const match=matchBinding(b.dataBinding,doc);result.push({key,kind,label:b.dataBinding?.label||b.title||'Parte sem vínculo',...match});}return result;}
export function resolveBlockBinding(b,doc,matches={}){const kind=bindingKind(b);if(!kind)return null;const key=bindingSlot(b),list=kind==='ability'?doc.abilities:doc.rituals,explicit=Object.prototype.hasOwnProperty.call(matches,key),match=explicit?{entity:list.find(e=>e.id===matches[key]),reason:'Sem correspondência escolhida.'}:matchBinding(b.dataBinding,doc);delete b.ref;delete b.abilityIndex;delete b.ritualIndex;if(match.entity){b.ref=match.entity.id;b.dataBinding=entityDescriptor(match.entity,kind);delete b.bindingIssue;return null;}b.bindingIssue={kind,label:b.dataBinding?.label||b.title||'Parte sem vínculo',reason:match.reason};return clone(b.bindingIssue);}
